() => {
  // Rebased on mulberry32-v1: action 11 has three incompatible coastal attempts.
  const h = createGenerationHarness(2);
  for (let i = 0; i < 10; i++) {
    const app = h.render();
    app.safelyAddRegionToMap(i ? app.candidateHexes[0] : { q: 0, r: 0 }, {
      targetSize: 20, coastalPreference: i ? 'auto' : 'mainland'
    });
    assert.equal(h.render().regions.length, i + 1);
  }
  const before = h.render();
  const oldRegions = JSON.stringify(before.regions);
  const oldRivers = JSON.stringify(before.rivers);
  const anchor = before.candidateHexes[0];
  h.logs.length = 0;
  before.safelyAddRegionToMap(anchor, { targetSize: 20, coastalPreference: 'auto' });
  const after = h.render();
  assert.equal(after.regions.length, 11);
  assert.ok(!after.regions.at(-1).isTract);
  assert.equal(after.regions.at(-1).hexes.length, 20);
  const event = h.logs.filter(log => log.args[0] === '[generation]').at(-1).args[1];
  assert.equal(event.kind, 'generated');
  assert.equal(event.attempt, 4);
  assert.equal(event.rejectionCounts.coastal_river_endpoints_incompatible, 3);
  assert.equal(JSON.stringify(after.regions.slice(0, -1)), oldRegions);
  assert.equal(after.history.length, before.history.length + 1);
  const built = h.geometry.buildRegionRiverNetwork(after.rivers, [], after.regions, after.candidateHexes, after.hexTerrainByKey, true);
  assert.equal(built.issues.length, 0);
  assert.equal(validateRiverNetwork(built.network).valid, true);
  h.geometry.assertHexcrawlSaveData(JSON.parse(JSON.stringify(after.createSaveData())));
  const document=structuredClone(after.captureDocument()),stacks=structuredClone([after.undoHistory,after.redoHistory]);let prompt='';
  h.setWindow({confirm:message=>{prompt=message;return false;}});after.deleteLastRegion();
  assert.match(prompt,/Будет восстановлено исходное состояние рек/);assert.deepEqual(structuredClone(h.render().captureDocument()),document);assert.deepEqual(structuredClone([h.render().undoHistory,h.render().redoHistory]),stacks);
  h.setWindow({confirm:()=>true});h.render().deleteLastRegion();
  assert.equal(JSON.stringify(h.render().regions), oldRegions);
  assert.equal(JSON.stringify(h.render().rivers), oldRivers);
}

() => {
  const { geometry: rules } = createGenerationHarness(1);
  assert.equal(biomes.length, Object.keys(rules.BIOMES).length);
  assert.deepEqual(biomes.map(id => rules.BIOMES[id]?.id), biomes);
  const expected = [
    ['dead_forest', 'Мёртвый лес', 1],
    ['dead_woodland', 'Мёртвое редколесье', 1],
    ['dead_forested_hills', 'Мёртвый лес на холмах', 2],
    ['dead_mountain_forest', 'Мёртвый горный лес', 3]
  ];
  for (const [id, label, height] of expected) {
    assert.equal(rules.BIOMES[id].label, label);
    assert.equal(rules.BIOMES[id].heightLevel, height);
    assert.equal(rules.BIOMES[id].wildWeight, 1);
    assert.equal(rules.BIOMES[id].settledWeight, 0);
    for (const [index, neighbour] of biomes.entries()) {
      const expectedCompatibility = !invalid.get(id).includes(index + 1)
        && !(invalid.get(neighbour)?.includes(biomes.indexOf(id) + 1));
      assert.equal(rules.isBiomesCompatible(id, neighbour, rules.BIOME_COMPATIBILITY_MATRIX), expectedCompatibility, `${id} → ${neighbour}`);
      assert.equal(rules.isBiomesCompatible(neighbour, id, rules.BIOME_COMPATIBILITY_MATRIX), expectedCompatibility, `${neighbour} → ${id}`);
    }
  }
}

() => {
  for (const height of [1, 2, 3]) {
    for (let seed = 1; seed <= 30; seed++) {
      const { geometry: rules } = createGenerationHarness(seed);
      const result = rules.chooseBiomeIdAtHeightLevel('settled', [], seed, height);
      if (result.biomeId) assert.ok(rules.BIOMES[result.biomeId].settledWeight > 0);
    }
  }
}

() => {
  for (const id of invalid.keys()) {
    const h = createGenerationHarness(41);
    h.render().addFallbackTractToMap({ q: 0, r: 0 }, true, { landType: 'wild', biomeId: id });
    const created = h.render();
    assert.equal(created.regions[0].biomeId, id);
    assert.equal(created.regions[0].heightLevel, h.geometry.BIOMES[id].heightLevel);
    const saved = JSON.parse(JSON.stringify(created.createSaveData()));
    h.geometry.assertHexcrawlSaveData(saved);
    created.deleteLastRegion();
    assert.equal(h.render().regions.length, 0);
  }
}

async()=>{
 const {data,key}=entityNameFixture(type),h=await setup(data),before=save(h),history=stacks(h);
 name(h,key);const after=save(h);assert.deepEqual(after.map.editorNames,{[key]:{ru:'Старое имя',en:'Old name'}});
 assert.equal(h.render().undoHistory.length,history[0].length+1);assert.deepEqual(after.generation,before.generation);assert.deepEqual(after.counters,before.counters);
