()=>{
 for(const e of FOREST_EDGES)for(let v=0;v<4;v++){
  const ss=reflectForestEdge(e.segments,v);
  assert.deepEqual(ss[0].start,[0,0]);assert.deepEqual(ss.at(-1).end,[1,0]);
