      const alerts=[];t.setWindow({alert:m=>alerts.push(m),matchMedia:()=>({matches:false})});
      const before=JSON.stringify(t.render().captureDocument()),stacks=JSON.stringify([t.render().undoHistory,t.render().redoHistory]);
