  const first = harness.render();
  first.safelyAddRegionToMap(first.candidateHexes[0], { targetSize: 8 });
  const before = harness.render();
  const editedFirst = renameToponym(before.toponyms, 'region:1', 'Northwatch', 'Нортвотч');
